// CashedOutPosition A qualifying cash-out (early sell before contract resolution) with cost-basis context. Exposed only via the `withCashOuts=true` sibling array on `POST /v1/prediction-markets/positions/settled`. Distinct from `SettledPosition` — cash-outs don't have a `payout` or `resolutionSide` since the contract hadn't resolved when the user sold.
type CashedOutPosition struct {
	// AccountId Account that held the position.
	AccountId        int64             `json:"accountId"`
	ContractMetadata *ContractMetadata `json:"contractMetadata,omitempty"`

	// CostBasis Cost basis allocated proportionally to the filled quantity (`(costBasisSpend / costBasisPositionBalance) * filledQuantity`).
	CostBasis string `json:"costBasis"`

	// FilledQuantity Quantity sold (cumulative filled quantity on the cash-out order).
	FilledQuantity string `json:"filledQuantity"`

	// InstrumentId Contract instrument ID.
	InstrumentId int64 `json:"instrumentId"`

	// InstrumentSymbol Contract instrument symbol.
	InstrumentSymbol string `json:"instrumentSymbol"`

	// NetProfit Realized P&L from this cash-out fill (`proceeds - costBasis`). Equals the ledger `realized_pl` delta on the position-balance row pair around the fill; falls back to `0` under transient market-data lag so a missing post-fill snapshot can't poison the page.
	NetProfit string `json:"netProfit"`

	// Proceeds Amount received from the sale in USD. For prediction sells, proceeds flow through `cash_balance` rather than `closed_orders.total_spend`, so the value is derived from position-balance snapshots before/after the fill.
	Proceeds string `json:"proceeds"`

	// Side Always `sell` for cash-outs.
	Side CashedOutPositionSide `json:"side"`

	// Timestamp Wall-clock timestamp when the cash-out order closed (ISO 8601).
	Timestamp time.Time `json:"timestamp"`
}

